// Loop over all incoming items
for (const item of $input.all()) {
  const email = item.json;

  // Grab the Subject and Sender, and convert to lowercase 
  // (We use || "" just in case the field is empty so it doesn't crash)
  const subject = (email.Subject || "").toLowerCase();
  const sender = (email.From || "").toLowerCase();

  // Keywords indicating job-related emails
  const jobKeywords = [
      "internship", "intern", "interview", "hiring", "career",
      "job", "assessment", "offer", "recruitment", "application",
      "candidate", "hr", "selection", "joining", "onboarding", "placement"
  ];

  // Keywords to ignore
  const ignoreKeywords = [
      "otp", "invoice", "receipt", "amazon", "flipkart", "netflix",
      "youtube", "instagram", "facebook", "security alert",
      "verification code", "password", "bank", "electricity", "transaction"
  ];

  // Check if any job keyword is in the subject or sender
  const isJobEmail = jobKeywords.some(keyword => 
      subject.includes(keyword) || sender.includes(keyword)
  );

  // Check if any ignore keyword is in the subject
  const isIgnored = ignoreKeywords.some(keyword => 
      subject.includes(keyword)
  );

  // Determine whether to continue
  const shouldContinue = isJobEmail && !isIgnored;

  // Add the new field right into our email object
  email.shouldContinue = shouldContinue;
}

// Return the updated items to the next node
return $input.all();
